import React, { useEffect, useState } from "react";
import { motion, AnimatePresence } from "framer-motion";

const WorkerSplash = ({ onComplete }) => {
  const [isExiting, setIsExiting] = useState(false);

  useEffect(() => {
    const timer = setTimeout(() => setIsExiting(true), 3200);
    const finish = setTimeout(onComplete, 4200);
    return () => { clearTimeout(timer); clearTimeout(finish); };
  }, [onComplete]);

  return (
    <div className="h-screen w-full bg-[#FDFAD8] flex items-center justify-center relative overflow-hidden">

      {/* 1. THE "LIQUID" ORB (Apple-style depth) */}
      <motion.div 
        initial={{ scale: 0.8, opacity: 0 }}
        animate={{ scale: 1.5, opacity: 0.2 }}
        transition={{ duration: 3, ease: "easeOut" }}
        className="absolute w-[600px] h-[600px] bg-[#CAD23C] rounded-full blur-[120px]"
      />

      {/* 2. THE CONTENT UNIT */}
      <div className={`${isExiting ? "animate-apple-exit" : ""}`}>
        <div className="flex flex-col items-center">

          {/* THE LOGO: Morphing Entrance */}
          <div className="flex items-baseline overflow-hidden px-4">
            <motion.h1 
              initial={{ y: 200 }}
              animate={{ y: 0 }}
              transition={{ duration: 1.2, ease: [0.16, 1, 0.3, 1] }}
              className="text-[10rem] md:text-[14rem] font-[1000] text-[#47510B] tracking-tighter italic"
            >
              T
            </motion.h1>

            <motion.div 
              initial={{ opacity: 0, scale: 0.5, rotate: -45 }}
              animate={{ opacity: 1, scale: 1, rotate: 0 }}
              transition={{ duration: 1, delay: 0.5, ease: "easeOut" }}
              className="mx-2 mb-8"
            >
              <div className="bg-[#FF5B03] w-20 h-20 md:w-28 md:h-28 rounded-[2rem] flex items-center justify-center shadow-2xl rotate-12 animate-soft-glow">
                <span className="text-white text-6xl md:text-7xl font-black italic">2</span>
              </div>
            </motion.div>

            <motion.h1 
              initial={{ y: 200 }}
              animate={{ y: 0 }}
              transition={{ duration: 1.2, delay: 0.2, ease: [0.16, 1, 0.3, 1] }}
              className="text-[10rem] md:text-[14rem] font-[1000] text-[#47510B] tracking-tighter italic"
            >
              T
            </motion.h1>
          </div>

          {/* THE SUBTEXT: Minimalist Fade-in */}
          <motion.div 
            initial={{ opacity: 0, letterSpacing: "0.2em" }}
            animate={{ opacity: 1, letterSpacing: "1.2em" }}
            transition={{ duration: 2, delay: 1 }}
            className="mt-[-20px] text-[#47510B] font-black text-sm uppercase pl-[1.2em]"
          >
            Worker
          </motion.div>
        </div>
      </div>

      {/* 3. DYNAMIC PROGRESS LINE (Apple thinness) */}
      <div className="absolute bottom-20 w-32 h-[2px] bg-[#47510B]/10 rounded-full overflow-hidden">
        <motion.div 
          initial={{ x: "-100%" }}
          animate={{ x: "100%" }}
          transition={{ duration: 3, ease: "easeInOut" }}
          className="h-full bg-[#FF5B03] w-1/2"
        />
      </div>

      {/* 4. PERIMETER INFO (Very subtle, clean) */}
      <div className="absolute bottom-8 w-full px-12 flex justify-between text-[10px] font-bold text-[#47510B] opacity-20 uppercase tracking-[0.2em]">
        <span>T2T_Network</span>
        <span>Operational</span>
      </div>
    </div>
  );
};

export default WorkerSplash;
